const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const sigma = 0.05;
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
const k = Math.min(128, pts.length);
const {eigenvalues, eigenvectors} = laplacian.eigen({maxFirst: false, k, maxIterations: 200, tolerance: 1e-2});
const eigenArrays = eigenvectors.map(eigenvector => eigenvector.toArray());

let source = 0;
let simLoop = null;
const modalY = new Array(k).fill(0); // modal positions
const modalV = new Array(k).fill(0); // modal velocities

// x = U * y
const computePositions = () => {
    const x = new Array(pts.length).fill(0);
    for (let i = 0; i < k; i++) {
        const u = eigenArrays[i];
        const y = modalY[i];
        for (let p = 0; p < x.length; p++) x[p] += u[p] * y;
    }
    return x;
};

const clamp = x => Math.min(1, Math.max(0, x));
const r = 10 / 4;
const toColors = values => {
    const finite = values.filter(Number.isFinite);
    const max = finite.reduce((value, x) => Math.max(value, x), Number.NEGATIVE_INFINITY);
    const min = finite.reduce((value, x) => Math.min(value, x), Number.POSITIVE_INFINITY);
    const range = max - min;
    const isConstant = !(range > 0.05 * Math.max(Math.abs(max), Math.abs(min)));
    return values.map(value => {
        const x = isConstant || !Number.isFinite(value) ? 0.5 : (value - min) / range;
        return [clamp(r * x), clamp(r * (x - 0.4)), clamp(5 * (x - 0.8))];
    });
};

const points = pts.map(point => point.toArray());
const triangles = faces.map(({vertices: indices}) => indices.map(index => points[index]));
const triangleColors = colors => faces.map(({vertices: indices}) => indices.map(vertexIndex => colors[vertexIndex]));

const pointPlot = IO.plotPointCloud(points, {color: toColors(computePositions())});
const trianglePlot = IO.plotTriangleCloud(triangles, {color: triangleColors(toColors(computePositions()))});

const updatePlot = () => {
    const colors = toColors(computePositions());
    pointPlot.update(points, {color: colors});
    trianglePlot.update(triangles, {color: triangleColors(colors)});
    pointPlot.render();
    trianglePlot.render();
};

const resetSimulation = () => {
    stopSimulation();
    for (let i = 0; i < k; i++) {
        modalY[i] = eigenArrays[i][source];
        modalV[i] = 0;
    }
    updatePlot();
};

const startSimulation = async () => {
    if (simLoop) return;

    const dt = 0.06; // Fixed time step

    simLoop = await IO.loop(() => {
        // Symplectic Euler integration step for each independent mode:
        for (let i = 0; i < k; i++) {
            modalV[i] -= dt * eigenvalues[i] * modalY[i];
            modalY[i] += dt * modalV[i];
        }
        updatePlot();
    });
    simLoop.play();
};

function stopSimulation() {
    if (simLoop) simLoop.stop();
    simLoop = null;
}

resetSimulation();

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => trianglePlot},
    ]},
    {
        type: "group",
        value: () => [
            {type: "button", value: () => ({title: "Reset", onClick: () => { stopSimulation(); resetSimulation(); }})},
            {type: "button", value: () => ({title: "Start", onClick: () => { startSimulation(); }})},
            {type: "button", value: () => ({title: "Pause", onClick: () => { stopSimulation(); }})},
        ]
    },
    {type: "slider", value: () => ({
        min: 0,
        max: pts.length - 1,
        step: 1,
        value: source,
        title: "Wave source vertex:",
        onChange: value => {
            source = Math.round(value);
            resetSimulation();
        },
    })},
);
ui;
